<script setup lang="ts">
import { computed, ref } from 'vue';
import { Head, Link } from '@inertiajs/vue3';
import DashboardLayout from '../layouts/DashboardLayout.vue';
import SchoolDashboardView from '../components/SchoolDashboard.vue';
import AppIcon from '../components/AppIcon.vue';
import MetricCard from '../components/MetricCard.vue';
import TrendChart from '../components/TrendChart.vue';
import SchoolTable from '../components/SchoolTable.vue';
import { schoolGroups, schoolPages } from '../navigation';
import { money } from '../format';
import type { School, Plan, SchoolDashboard, LiveAcademic } from '../types';
const props = defineProps<{ page: string; schools: School[]; selectedSchool: School | null; plans: Plan[]; sampleMonths: string[]; sampleDate: string; dashboard: SchoolDashboard | null; liveAcademic: LiveAcademic | null; academicEnabled: boolean }>();
const search = ref(''), planFilter = ref('all');
const titles: Record<string, string> = { overview: 'Platform dashboard', schools: 'Schools directory', profile: 'School profile', plans: 'Subscription plans', dashboard: 'School dashboard', settings: 'System settings', students: 'Students', academics: 'Academics', attendance: 'Attendance', examinations: 'Examinations', fees: 'Fee Collection', ...Object.fromEntries(schoolGroups.flatMap(g=>g.items.map(i=>[i.page,i.label]))) };
const title = computed(()=>titles[props.page] ?? 'Workspace');
const isSchoolPage = computed(()=>schoolPages.includes(props.page));
const schoolUrl = computed(()=>props.selectedSchool ? `/preview/schools/${props.selectedSchool.slug}` : '/preview/schools');
const modules = schoolGroups.flatMap(g=>g.items);
const totals = computed(()=>props.schools.reduce((a,s)=>({students:a.students+s.students,teachers:a.teachers+s.teachers,monthly:a.monthly+s.monthly_price_minor,classrooms:a.classrooms+s.classrooms}),{students:0,teachers:0,monthly:0,classrooms:0}));
const trend = computed(()=>props.sampleMonths.map((_,i)=>props.schools.reduce((sum,s)=>sum+s.trend[i]!,0)));
const growth = computed(()=>trend.value[0] ? Math.round((trend.value.at(-1)!/trend.value[0]!-1)*100) : 0);
const filtered = computed(()=>props.schools.filter(s=>`${s.name} ${s.city}`.toLowerCase().includes(search.value.toLowerCase()) && (planFilter.value==='all'||s.plan===planFilter.value)));
</script>
<template>
<Head :title="title"/>
<DashboardLayout v-slot="{ dark, toggleTheme }" :page="page" :title="title" :schools="schools" :selected-school="selectedSchool" :dashboard="dashboard">
    <div class="page-heading"><div><h1>{{ page==='dashboard' ? 'Dashboard' : title }}</h1><p>{{ page==='dashboard' ? 'Your people, progress, and priorities at a glance.' : page==='overview' ? 'Schools, subscriptions, and the health of your SaaS platform.' : page==='schools' ? 'Explore your independent demo school workspaces.' : page==='plans' ? 'Platform subscriptions, separate from school fee collection.' : page==='settings' ? 'Local environment and workspace preferences.' : 'Explore your selected school?s read-only preview.' }}</p></div><div class="heading-tools"><span class="academic-year">Academic year <strong>{{ selectedSchool?.settings.academic_year ?? '2026?2027' }}</strong></span><span class="heading-action"><AppIcon name="calendar" :size="14"/>{{ sampleDate }}</span></div></div>
    <SchoolDashboardView v-if="page==='dashboard' && selectedSchool && dashboard" :school="selectedSchool" :data="dashboard" :months="sampleMonths" :live="liveAcademic"/>
    <section v-else-if="page==='dashboard'" class="panel empty"><h2>No demo school selected</h2><p>Seed the local demo catalog or select an available demo school.</p><Link href="/preview/schools" class="text-link">Open schools directory</Link></section>
            <template v-else-if="page==='overview'">
                <div class="metric-grid"><MetricCard :label="isSchoolPage ? 'Students*' : 'Demo schools'" :value="isSchoolPage ? selectedSchool?.students.toLocaleString() ?? '0' : schools.length" :detail="isSchoolPage ? 'Illustrative enrollment' : 'Across '+new Set(schools.map(s=>s.city)).size+' cities'" icon="▦"/><MetricCard :label="isSchoolPage ? 'Teachers*' : 'Total students*'" :value="(isSchoolPage ? selectedSchool?.teachers ?? 0 : totals.students).toLocaleString()" detail="Deterministic sample data" icon="♧" tone="green"/><MetricCard :label="isSchoolPage ? 'Classrooms*' : 'Total teachers*'" :value="isSchoolPage ? selectedSchool?.classrooms ?? 0 : totals.teachers" detail="Across demo campuses" icon="▤" tone="orange"/><MetricCard :label="isSchoolPage ? 'Platform plan' : 'Monthly plan value*'" :value="isSchoolPage ? selectedSchool?.plan ?? '—' : money(totals.monthly)" :detail="isSchoolPage ? 'Demo subscription · no billing' : 'Illustrative · not collected revenue'" icon="◇" tone="blue"/></div>
                <div class="dashboard-grid"><section class="panel growth-panel"><div class="panel-heading"><div><h2>Enrollment overview <span class="sample-tag">SAMPLE</span></h2><p>How your {{ isSchoolPage ? 'school is' : 'schools are' }} growing over time</p></div><span class="subtle-chip">Last 6 months</span></div><div class="chart-summary"><strong>{{ trend.at(-1)?.toLocaleString() ?? 0 }}</strong><span class="growth-pill">↗ {{ growth }}%</span><span class="muted">over sample period</span></div><TrendChart :values="trend" :labels="sampleMonths"/></section>
                <section class="panel distribution"><div class="panel-heading"><div><h2>Plan distribution</h2><p>Demo schools by subscription</p></div><span class="muted">◇</span></div><div class="donut-wrap"><div class="donut" :style="{background: `conic-gradient(${plans.map((p,i) => `${['#188d76','#7fc3ae','#c8e3d9'][i%3]} ${plans.slice(0,i).reduce((a,p)=>a+p.schools,0)/Math.max(schools.length,1)*100}% ${plans.slice(0,i+1).reduce((a,p)=>a+p.schools,0)/Math.max(schools.length,1)*100}%`).join(',')})`}"><div><strong>{{ schools.length }}</strong><span>demo schools</span></div></div></div><div class="legend"><div v-for="(p,i) in plans" :key="p.code"><span class="legend-dot" :style="{background:['#188d76','#7fc3ae','#c8e3d9'][i%3]}"/>{{ p.name }}<strong>{{ p.schools }} <span>{{ Math.round(p.schools/Math.max(schools.length,1)*100) }}%</span></strong></div></div></section></div>
                <section class="panel school-panel"><div class="panel-heading"><div><h2>{{ isSchoolPage ? 'Your campus' : 'Your schools' }} <span class="count-chip">{{ isSchoolPage ? 1 : schools.length }}</span></h2><p>A connected community of learning</p></div><Link href="/preview/schools" class="text-link">View all schools <span>↗</span></Link></div><SchoolTable :schools="isSchoolPage && selectedSchool ? [selectedSchool] : schools"/></section>
                <div class="footnote">* Illustrative metrics from the demo catalog. No student, attendance, payment, or examination records are created.</div>
            </template>

            <template v-else-if="page==='schools'"><div class="directory-summary"><span class="mini-icon">▦</span><strong>{{ schools.length }} demo schools</strong><span>Independent workspaces. Shared possibilities.</span></div><section class="panel"><div class="directory-tools"><label class="search-box"><span>⌕</span><input v-model="search" type="search" placeholder="Search schools or cities…" aria-label="Search schools"/></label><select v-model="planFilter" aria-label="Filter subscription plans" class="filter-select"><option value="all">All plans</option><option v-for="p in plans" :key="p.code">{{ p.name }}</option></select><span class="muted">{{ filtered.length }} results</span></div><SchoolTable :schools="filtered"/></section></template>

            <template v-else-if="page==='profile' && selectedSchool"><div class="profile-hero panel"><span class="large-avatar" :style="{background:selectedSchool.color+'18',color:selectedSchool.color}">{{ selectedSchool.name.split(' ').map(s=>s[0]).slice(0,2).join('') }}</span><div><h2>{{ selectedSchool.name }}</h2><p>{{ selectedSchool.city }} · {{ selectedSchool.domain }}</p><span class="status"><i/>Demo school</span></div><Link class="primary-link" :href="schoolUrl+'/dashboard'">Open school preview ↗</Link></div><div class="two-columns"><section class="panel"><div class="panel-heading"><div><h2>School configuration</h2><p>Seeded settings · read only</p></div><span>⚙</span></div><dl class="details"><div><dt>School slug</dt><dd>{{ selectedSchool.slug }}</dd></div><div v-for="(value,key) in selectedSchool.settings" :key="key"><dt>{{ String(key).replaceAll('_',' ') }}</dt><dd>{{ value }}</dd></div><div><dt>Hostname</dt><dd>{{ selectedSchool.domain }}<small>Reserved .test domain; DNS setup required</small></dd></div></dl></section><section class="panel"><div class="panel-heading"><div><h2>Platform subscription</h2><p>Separate from future student fee billing</p></div><span>◇</span></div><div class="subscription-preview"><span class="plan-chip">{{ selectedSchool.plan }}</span><h3>{{ money(selectedSchool.monthly_price_minor) }}<small>/ month</small></h3><p>Demo plan value. No payment processing, invoices, or real transactions.</p><Link href="/preview/plans" class="text-link">Explore plan definitions ↗</Link></div></section></div></template>

            <template v-else-if="page==='plans'"><div class="info-strip">◇ <span>Platform subscription definitions only. Billing and payment processing are not enabled.</span></div><div class="plan-grid"><section v-for="p in plans" :key="p.code" class="panel pricing-card" :class="{featured:p.name==='Growth'}"><span v-if="p.name==='Growth'" class="recommended">ROOM TO GROW</span><span class="eyebrow">{{ p.name.toUpperCase() }}</span><h2>{{ p.name }}</h2><p>For schools with up to {{ p.capacity.toLocaleString() }} students</p><div class="price">{{ money(p.monthly_price_minor) }}<small>/ month</small></div><span class="plan-preview-label">DEMO PLAN · {{ p.schools }} SCHOOLS</span><ul><li v-for="feature in p.features" :key="feature"><span>✓</span>{{ feature }}</li><li><span>✓</span>Independent school workspace</li></ul><div class="plan-unavailable">Subscription changes available in a future phase</div></section></div></template>

            <template v-else-if="page==='settings'"><div class="two-columns"><section class="panel"><div class="panel-heading"><div><h2>Environment</h2><p>Phase 1 configuration overview</p></div><span>⚙</span></div><dl class="details"><div><dt>Workspace mode</dt><dd><span class="status"><i/>Local preview</span></dd></div><div><dt>Data source</dt><dd>Seeded demo schools</dd></div><div><dt>Preview access</dt><dd>Local + explicit configuration</dd></div><div><dt>Write operations</dt><dd>{{ academicEnabled?'Local academic CRUD enabled':'Disabled' }}</dd></div><div><dt>Authentication</dt><dd>Not implemented in Phase 1</dd></div><div><dt>Production management</dt><dd>Unavailable</dd></div></dl></section><section class="panel"><div class="panel-heading"><div><h2>Appearance</h2><p>A workspace that works for you</p></div><span>◐</span></div><div class="appearance"><div class="theme-preview" :class="{night:dark}"><div/><aside/><section><i/><i/><i/></section></div><h3>{{ dark ? 'Dark' : 'Light' }} theme</h3><p>Saved in this browser only.</p><button class="secondary-button" @click="toggleTheme">Switch to {{ dark ? 'light' : 'dark' }} theme</button></div></section></div></template>

            <template v-else><section class="panel module-placeholder"><div class="placeholder-icon"><AppIcon :name="modules.find(m=>m.page===page)?.icon ?? 'academics'" :size="30"/></div><span class="eyebrow">MODULE PREVIEW</span><h2>{{ title }}, with a strong foundation.</h2><p>This module is a read-only placeholder for a future phase. {{ selectedSchool?.name ?? 'Select a demo school to explore its workspace.' }}</p><div class="placeholder-features"><span>School-scoped data</span><span>Membership authorization</span><span>Auditable workflows</span></div><div class="info-strip">No {{ title.toLowerCase() }} workflows or records are active in this preview.</div><Link :href="schoolUrl+'/dashboard'" class="text-link">← Back to school dashboard</Link></section></template>

</DashboardLayout>
</template>
